import React, { useState, useRef } from 'react';
import { Canvas, useThree, useFrame } from '@react-three/fiber';
import { OrbitControls, Environment, ContactShadows } from '@react-three/drei';
import { animated, useSpring } from '@react-spring/three';

import style from './style.module.css';

const positions: [number, number, number][] = [
  [0, 0.5, 0],
  [2, 0.5, 0],
  [-2, 0.5, 0],
  [0, 0.5, 2],
  [0, 0.5, -2],
];

const Box = ({
  position,
  onClick,
}: {
  position: [number, number, number];
  onClick: () => void;
}) => (
  <mesh position={position} castShadow receiveShadow onClick={onClick}>
    <boxGeometry args={[1, 1, 1]} />
    <meshStandardMaterial color="orange" />
  </mesh>
);

const Floor = () => (
  <mesh
    receiveShadow
    castShadow
    rotation={[-Math.PI / 2, 0, 0]}
    position={[0, 0, 0]}
  >
    <planeGeometry args={[10, 10]} />
    <meshStandardMaterial color="lightgray" />
  </mesh>
);

const CameraRig = ({ target }: { target: [number, number, number] }) => {
  const { camera } = useThree();

  const { camPos } = useSpring({
    camPos: [
      target[0] + 3,
      target[1] + 3,
      target[2] + 3,
    ] as [number, number, number],
    config: { mass: 1, tension: 170, friction: 26 },
  });

  useFrame(() => {
    camera.lookAt(...target);
  });

  return <animated.perspectiveCamera position={camPos} />;
};

const Scene = () => {
  const [target, setTarget] = useState<[number, number, number]>([0, 0, 0]);

  return (
    <>
      <ambientLight intensity={0.2} />
      <Environment preset="sunset" />
      <pointLight position={[10, 10, 10]} />

      <directionalLight
        castShadow
        position={[10, 10, 10]}
        intensity={10}
        shadow-mapSize-width={1024}
        shadow-mapSize-height={1024}
        shadow-camera-near={0.5}
        shadow-camera-far={20}
        shadow-camera-left={-10}
        shadow-camera-right={10}
        shadow-camera-top={10}
        shadow-camera-bottom={-10}
        shadow-bias={0.001}
      />

      {positions.map((pos, i) => (
        <Box key={i} position={pos} onClick={() => setTarget(pos)} />
      ))}

      <Floor />

      {/* <ContactShadows position={[0, 0, 0]} opacity={0.5} scale={10} blur={1.5} far={5} frames={Infinity}/> */}

      <OrbitControls />
      <CameraRig target={target} />
    </>
  );
};

const CanvasThree = () => {
  return (
    <div className={style.canvasContainer}>
      <Canvas
        shadows
        className={style.myCanvas}
        camera={{ position: [3, 3, 3], fov: 50 }}
      >
        <Scene />
      </Canvas>
    </div>
  );
};

const App = () => {
  return (
    <>
      <div>Three, React</div>
      <CanvasThree />
    </>
  );
};

export default App;
